provenance.sourcePrompt:
Opening title card — newspaper editorial style with animated text banner entry. 6s, 1920x1080, SILENT. Portrait photo background grayscale-treated. Text animates in using clip rect / clip-path reveal like .anim-text-banner. Typography uses Playfair Display SC for headline, EB Garamond for sub-text, Manrope for kicker. Double-border frame echoes the @mixin double-border style
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display+SC:wght@400;700&family=EB+Garamond:ital,wght@0,400;1,400&family=Manrope:wght@600;700&display=swap" rel="stylesheet">
<style>
root{
font:"EB Garamond",serif
font-title:"Playfair Display SC",serif
font-sans:"Manrope",sans-serif
black:#1c1f33
gray:#eee
}
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:var(--black);}
#scene{position:relative;}
/* portrait — grayscale, Ken Burns */
#bg{
position:absolute;top:0;left:0;width:100%;height:100%
object-fit:cover;z-index:1
filter:grayscale(95%) contrast(1.08) brightness(0.55)
transform-origin:50% 42%
}
/* paper texture overlay */
#paper{
position:absolute;top:0;left:0;width:100%;height:100%;z-index:2
background:repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(28,31,51,0.06) 3px,rgba(28,31,51,0.06) 4px)
}
/* bottom gradient */
#grad{
position:absolute;bottom:0;left:0;width:100%;height:65%;z-index:3
background:linear-gradient(to top,rgba(28,31,51,0.95) 0%,rgba(28,31,51,0.60) 50%,transparent 100%)
}
/* double-border frame */
#frame{
position:absolute
bottom:80px;left:80px
z-index:10
border:2px solid transparent
outline:3px solid rgba(238,238,238,0.70)
box-shadow:inset 0 0 0 1px rgba(238,238,238,0.70)
padding:32px 40px 36px
max-width:1100px
}
/* anim-text-banner style: each span uses clip-path reveal */
anim-line{
display:block
overflow:hidden
line-height:1.05
}
anim-line > span{
display:block
transform:translateY(108%)
opacity:0
}
/* Typography hierarchy */
kicker{
font:700 14px/1 var(--font-sans)
letter-spacing:.36em;text-transform:uppercase
color:#d72f2f;margin-bottom:14px
}
kicker span{display:inline;}
headline{
font:400 90px/.92 var(--font-title)
color:var(--gray)
letter-spacing:.01em
text-transform:uppercase
margin-bottom:16px
}
sub{
font:italic 24px/1.3 var(--font)
color:rgba(238,238,238,0.68)
letter-spacing:.03em
margin-top:14px
border-top:1px solid rgba(238,238,238,0.30)
padding-top:12px
}
#fade{position:absolute;inset:0;z-index:50;background:var(--black);opacity:0;pointer-events:none;}
</style>
</head>
<body>
<div id="scene">
<img id="bg" src="{{hero}}" alt="">
<div id="paper"></div>
<div id="grad"></div>
<div id="fade"></div>
<div id="frame">
<div class="kicker"><span id="k1">Benedict Cumberbatch</span></div>
<div class="headline">
<div class="anim-line"><span id="h1">A Star</span></div>
<div class="anim-line"><span id="h2">In Focus</span></div>
</div>
<div class="sub">
<div class="anim-line"><span id="s1">London, 1976 &nbsp;·&nbsp; Stage · Screen · Strange Dimensions</span></div>
</div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
var tl=gsap.timeline()
/* Ken Burns on portrait */
tl.fromTo('#bg',{scale:1.0,transformOrigin:'50% 42%'},{scale:1.05,duration:6,ease:'none'},0)
/* kicker fades in */
tl.to('#k1',{opacity:1,duration:0.5,ease:'power2.out'},0.3)
/* headline — clip reveal line by line (translateY 108% → 0) */
tl.to('#h1',{y:0,opacity:1,duration:0.72,ease:'power4.out'},0.55)
tl.to('#h2',{y:0,opacity:1,duration:0.72,ease:'power4.out'},0.66)
/* subline */
tl.to('#s1',{y:0,opacity:1,duration:0.6,ease:'power3.out'},1.15)
/* exit */
tl.to('#frame',{opacity:0,y:-16,duration:0.55,ease:'power2.in'},5.1)
tl.to('#fade', {opacity:1,duration:0.7,ease:'power2.inOut'},5.3)
})
</script>
</body>
</html>
```
